/**
 * Byte-identity regression: plans generated by the v0.10.0 engine (before the 0.11 features) must stay
 * exactly the same with every new option left at its default. The fixture is generated once from the
 * old engine (`GEN_BASELINE=1 npx vitest run tests/baseline.test.ts`) and must not be regenerated
 * to make a failing test pass.
 */
import { describe, expect, it } from 'vitest';
import { existsSync, readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { createHash } from 'node:crypto';
import {
  CYLINDERS, DEFAULT_SETTINGS, GENERIC_STANDARD, GUE_STANDARD, GasStandard, PlanSettings, planDive, planRecreational, ndl,
  planPenetration, Gas,
} from '../src/engine';

const FILE = join(__dirname, 'fixtures', 'baseline-plans.json');
// the engine adds new warning codes (gas density) in 0.11; everything else must match exactly
const NEW_CODES = new Set(['densityHigh', 'densityCritical']);

function build(): Record<string, unknown> {
  const out: Record<string, unknown> = {};
  const stds: GasStandard[] = [GUE_STANDARD, GENERIC_STANDARD];
  for (const std of stds) for (const d of [12, 21, 30, 45, 60, 80, 100]) for (const bt of [10, 25, 50]) for (const [lo, hi] of [[0.2, 0.85], [0.5, 0.8], [1, 1]]) {
    const bottom = std.bottomGasFor(d)?.gas ?? std.bottomGases[std.bottomGases.length - 1].gas;
    const deco = std.recommendedDecoGasesFor(d).map((x) => ({ gas: x.gas, switchDepth: x.switchDepth }));
    for (const at of ['next', 'current'] as const) {
      const settings: Partial<PlanSettings> = { ...DEFAULT_SETTINGS, gf: { low: lo, high: hi }, lastStopDepth: std.lastStopDepth, gfEvalAt: at, ascentRateShallowMpm: std.ascentRateShallowMpm };
      const p = planDive({ maxDepth: d, bottomTime: bt, bottomGas: bottom, decoGases: deco, settings });
      out[`tech ${std.id} ${d}/${bt} ${lo}/${hi} ${at}`] = { ...p, warnings: p.warnings.filter((w) => !NEW_CODES.has(w.code)) };
    }
  }
  const S12 = CYLINDERS.find((c) => c.name.startsWith('Single 12'))!;
  for (const d of [10, 18, 25, 30, 40]) for (const bt of [10, 30, 60]) for (const o2 of [0.21, 0.32]) {
    const gas: Gas = { o2, he: 0 };
    const p = planRecreational({ maxDepth: d, bottomTime: bt, gas, cylinder: S12, startBar: 200, sacLpm: 18, gfHigh: 0.85 });
    out[`rec ${d}/${bt} ${o2}`] = { ...p, warnings: p.warnings.filter((w) => !NEW_CODES.has(w.code)), blockers: p.blockers.filter((w) => !NEW_CODES.has(w.code)) };
    out[`ndl ${d} ${o2}`] = ndl(gas, d, 0.85);
  }
  const D12 = CYLINDERS[0];
  for (const maxDepth of [20, 30, 45]) {
    const p = planPenetration({
      agency: 'gue', environment: 'cave', flow: 'outflow', bottomGas: maxDepth > 30 ? { o2: 0.21, he: 0.35 } : { o2: 0.32, he: 0 }, stages: [], stageRule: 'halfPlus', stageReserveBar: 15,
      team: [{ id: 'a', name: 'A', cylinder: D12, startBar: 200, sacLpm: 18 }, { id: 'b', name: 'B', cylinder: D12, startBar: 200, sacLpm: 20 }],
      avgDepth: maxDepth - 5, maxDepth, swimSpeedMpm: 15, descentMinutes: 1, plannedPenetrationMinutes: 30,
      decoGases: [{ gas: { o2: 0.5, he: 0 }, switchDepth: 21 }], settings: { ...DEFAULT_SETTINGS },
    });
    out[`pen ${maxDepth}`] = { ...p, warnings: p.warnings.filter((w) => !NEW_CODES.has(w.code)), blockers: p.blockers.filter((w) => !NEW_CODES.has(w.code)) };
  }
  // one SHA-256 per case (exact JSON of the full result, incl. segments and tissue tensions) keeps the fixture small
  return Object.fromEntries(Object.entries(out).map(([k, v]) => [k, createHash('sha256').update(JSON.stringify(v)).digest('hex').slice(0, 32)]));
}

describe('baseline (defaults reproduce the v0.10.0 engine exactly)', () => {
  it('every plan matches the stored fixture', () => {
    const now = build();
    if (process.env.GEN_BASELINE === '1') {
      writeFileSync(FILE, JSON.stringify(now, null, 0).replace(/,"/g, ',\n"'));
      return;
    }
    expect(existsSync(FILE), 'baseline fixture missing').toBe(true);
    const ref = JSON.parse(readFileSync(FILE, 'utf8'));
    expect(Object.keys(now).sort()).toEqual(Object.keys(ref).sort());
    for (const k of Object.keys(ref)) expect(now[k], k).toEqual(ref[k]);
  });
});
